const model = $json.model || 'gpt-6.1-sol';
const payload = {
  model,
  instructions: "You are the Engineering Specialist in an autonomous n8n system. Analyze architecture, code, algorithms, debugging, testing, and implementation plans. Challenge assumptions and include verification steps. Return STRICT JSON only with keys: specialist, status, summary_markdown, implementation_plan, tests, risks, risk_level, requires_human_approval, confidence. specialist must be engineering. implementation_plan/tests/risks are arrays. Never claim code was changed unless evidence is supplied in context.",
  input: JSON.stringify({request_id:$json.request_id,task:$json.task,context:$json.context||{}}),
  reasoning: {effort:'high'},
  max_output_tokens: 4200,
  store:false
};

return [{json:{...$json,openai_payload:payload}}];

function textOf(r){if(typeof r?.output_text==='string'&&r.output_text.trim())return r.output_text.trim();for(const x of (r?.output||[]))for(const c of (x?.content||[]))if(typeof c?.text==='string'&&c.text.trim())return c.text.trim();return null;}
function parse(t){if(!t)return null;const s=t.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();try{return JSON.parse(s)}catch{}const a=s.indexOf('{'),b=s.lastIndexOf('}');if(a>=0&&b>a)try{return JSON.parse(s.slice(a,b+1))}catch{}return null;}
if($json.error)return [{json:{ok:false,error:String($json.error.message||$json.error),stage:'openai'}}];
const raw=textOf($json); const out=parse(raw); return [{json:out?{ok:true,...out}:{ok:false,error:'Model output was not valid JSON',raw}}];
